import{_ as i,a0 as u,w as l,s,ao as d,I as e,a1 as n,A as a,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Fedora Linux 的各種版本 | LCTT x X-CMD","titleTemplate":false,"description":"Fedora Linux 的各種版本 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Fedora Linux 的各種版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Fedora Linux 的各種版本 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20211203 Introduce the different Fedora Linux editions","title":"Fedora Linux 的各種版本","tag":"202209","desc":""},"relativePath":"202209/20211203 Introduce the different Fedora Linux editions.md","filePath":"[post].md"}'),p={name:"202209/20211203 Introduce the different Fedora Linux editions.md"};function f(F,r,m,x,b,g){const o=u("Link");return l(),s("div",null,[r[24]||(r[24]=d('<h1 id="fedora-linux-的各種版本" tabindex="-1">Fedora Linux 的各種版本 <a class="header-anchor" href="#fedora-linux-的各種版本" aria-label="Permalink to “Fedora Linux 的各種版本”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/11/FedoraMagz-FedoraEditions-Intro-816x345.png" alt="Introduce the differenct Fedora Linux editions"></p><p>我們在使用 Fedora Linux 時有不同的偏好。例如，有些人選擇 Fedora Linux，是因為 Fedora Workstation 默認使用 GNOME 作為其桌面環境。但也有一些人想使用 Fedora Linux 但想使用不同的桌面環境。或者也有一些人使用 Fedora Linux 有特定的需求，但不想被系統配置和應用安裝所困擾。甚至有些人想根據自己的需要自由安裝 Fedora Linux。因此 Fedora Linux 根據你的需要提供了多個版本。本文將介紹不同的 Fedora Linux 版本。</p><h3 id="fedora-官方版本" tabindex="-1">Fedora 官方版本 <a class="header-anchor" href="#fedora-官方版本" aria-label="Permalink to “Fedora 官方版本”">​</a></h3><p>我們從 Fedora Linux 的 <ruby>官方版本<rt>Edition</rt></ruby> 開始，即 Fedora Workstation、Fedora Server 和 Fedora IoT。 Fedora Workstation 是 Fedora Linux 的官方版本，可以安裝在筆記本電腦和台式電腦上。此版本附帶 GNOME 作為默認桌面環境和各種標準應用，因此 Fedora Linux 已為日常使用做好準備。而 Fedora Server 專門用於服務器用途，提供郵件服務器、DNS 等的安裝。最後一個是 Fedora IoT，用於物聯網和邊緣設備生態系統。</p><p>在 Fedora 項目網站主頁上，你可以找到另外兩個版本：Fedora CoreOS 和 Fedora Silverblue。Fedora CoreOS 是一個自動更新的操作系統，旨在安全、大規模地運行容器化工作負載。而 Fedora Silverblue 是一個不可變的桌面操作系統，旨在支持以容器為中心的工作流。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/11/g-monitor-overview.png" alt="Introduce the different Fedora Linux editions: Fedora Workstation"></p><p>更多信息可在此鏈接獲得：</p>',8)),e("blockquote",null,[e("p",null,[e("strong",null,[n(o,{href:"https://getfedora.org/"},{default:a(()=>[...r[0]||(r[0]=[t("https://getfedora.org/",-1)])]),_:1})])])]),r[25]||(r[25]=e("h3",{id:"fedora-定製版-可選桌面",tabindex:"-1"},[t("Fedora 定製版：可選桌面 "),e("a",{class:"header-anchor",href:"#fedora-定製版-可選桌面","aria-label":"Permalink to “Fedora 定製版：可選桌面”"},"​")],-1)),r[26]||(r[26]=e("p",null,[t("Fedora "),e("ruby",null,[t("定製版"),e("rt",null,"Spin")]),t(" 很受那些非常在意桌面外觀的人的歡迎。大多數人都知道 Fedora Linux 只有 GNOME 作為默認桌面環境。即使你真的想使用 GNOME 以外的桌面環境，也有幾個替代桌面選項。使用 Fedora 定製版，你可以在安裝 Fedora Linux 時立即獲得你最喜歡的桌面環境。你可以從 KDE Plasma、XFCE、LXQt、MATE、Cinnamon、LXDE 和 SoaS 中進行選擇。此外，對於喜歡平鋪窗口管理器的人，Fedora Linux 還提供了 Fedora i3 定製版，其中 i3 作為默認窗口管理器，並附帶了幾個標準應用。")],-1)),r[27]||(r[27]=e("p",null,[e("img",{src:"https://fedoramagazine.org/wp-content/uploads/2021/11/screenshot-kde-1024x640.jpg",alt:"Introduce the different Fedora Linux editions: Fedora Plasma"})],-1)),r[28]||(r[28]=e("p",null,[e("img",{src:"https://fedoramagazine.org/wp-content/uploads/2021/11/screenshot-cinnamon-1024x576.jpg",alt:"Introduce the different Fedora Linux editions: Fedora Cinnamon"})],-1)),r[29]||(r[29]=e("p",null,"更多信息可在此鏈接獲得：",-1)),e("blockquote",null,[e("p",null,[e("strong",null,[n(o,{href:"https://spins.fedoraproject.org/"},{default:a(()=>[...r[1]||(r[1]=[t("https://spins.fedoraproject.org/",-1)])]),_:1})])])]),r[30]||(r[30]=d('<h3 id="fedora-實驗室-功能包" tabindex="-1">Fedora 實驗室：功能包 <a class="header-anchor" href="#fedora-實驗室-功能包" aria-label="Permalink to “Fedora 實驗室：功能包”">​</a></h3><p>Fedora <ruby>實驗室<rt>Lab</rt></ruby> 是根據特定需求打包的 Fedora Linux 軟件包集合。因此，這些版本的安裝包都根據其功能提供了應用和必要的內容。Fedora 實驗室提供多種軟件包選擇，例如<ruby>天文學<rt>Astronomy</rt></ruby>、<ruby>計算神經學<rt>Comp Neuro</rt></ruby>、<ruby>設計套件<rt>Design Suite</rt></ruby>、<ruby>遊戲<rt>Games</rt></ruby>、JAM、<ruby>Python 教室<rt>Python Classroom</rt></ruby>、<ruby>安全實驗室<rt>Security Lab</rt></ruby>、<ruby>機器人套件<rt>Robotics Suite</rt></ruby> 和 <ruby>科學<rt>Scientific</rt></ruby>。如果你想使用 Fedora Linux 進行設計工作，那麼設計套件是你的正確選擇。但是如果你喜歡玩遊戲，你可以選擇遊戲版。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/11/Fedora-Design-1024x792.png" alt="Introduce the different Fedora Linux editions: Fedora Design Suite"></p><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/11/Fedora-Games-1024x792.png" alt="Introduce the different Fedora Linux editions: Fedora Games"></p><p>更多信息可在此鏈接獲得：</p>',5)),e("blockquote",null,[e("p",null,[e("strong",null,[n(o,{href:"https://labs.fedoraproject.org/"},{default:a(()=>[...r[2]||(r[2]=[t("https://labs.fedoraproject.org/",-1)])]),_:1})])])]),r[31]||(r[31]=d('<h3 id="fedora-的其它下載" tabindex="-1">Fedora 的其它下載 <a class="header-anchor" href="#fedora-的其它下載" aria-label="Permalink to “Fedora 的其它下載”">​</a></h3><p>Fedora 的<ruby>其它下載<rt>Alt Download</rt></ruby> 集合了特定目的的可選 Fedora Linux 安裝程序，例如用於測試或用於特定架構。還有其他可選格式，例如網絡安裝程序或種子下載等格式。在這裏你可以找到<ruby>網絡安裝程序<rt>Network Installer</rt></ruby>、<ruby>種子下載<rt>Torrent Downloads</rt></ruby>、<ruby>可選架構<rt>Alternative Architectures</rt></ruby>、<ruby>雲基礎鏡像<rt>Cloud Base Images</rt></ruby>、<ruby>所有內容<rt>Everything</rt></ruby>、<ruby>測試鏡像<rt>Testing Images</rt></ruby> 和 Rawhide。</p><p>更多信息可在此鏈接獲得：</p>',3)),e("blockquote",null,[e("p",null,[e("strong",null,[n(o,{href:"https://alt.fedoraproject.org/"},{default:a(()=>[...r[3]||(r[3]=[t("https://alt.fedoraproject.org/",-1)])]),_:1})])])]),r[32]||(r[32]=e("h3",{id:"總結",tabindex:"-1"},[t("總結 "),e("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),r[33]||(r[33]=e("p",null,"你可以自由選擇適合你偏好的 Fedora Linux 版本，而不是官方版本。但是，如果你想獲得具有各種桌面外觀的 Fedora Linux，那麼 Fedora 定製版適合你。如果你希望 Fedora Linux 根據你的需要包含應用和軟件包，你可以選擇 Fedora 實驗室。但是，如果你是專家並且想要更自由地安裝 Fedora Linux，你可以在 Fedora 其它下載處瀏覽替代選項。希望本文可以幫助你選擇合適的 Fedora Linux，並請在評論中分享你使用 Fedora Linux 的經驗。",-1)),e("p",null,[r[6]||(r[6]=t("（題圖由 ",-1)),n(o,{href:"https://unsplash.com/@fredericp?utm_source=unsplash&utm_medium=referral&utm_content=creditCopyText"},{default:a(()=>[...r[4]||(r[4]=[t("Frédéric Perez",-1)])]),_:1}),r[7]||(r[7]=t(" 發佈在 ",-1)),n(o,{href:"https://unsplash.com/s/photos/blue-abstract?utm_source=unsplash&utm_medium=referral&utm_content=creditCopyText"},{default:a(()=>[...r[5]||(r[5]=[t("Unsplash",-1)])]),_:1}),r[8]||(r[8]=t("）",-1))]),r[34]||(r[34]=e("hr",null,null,-1)),e("p",null,[r[10]||(r[10]=t("via: ",-1)),n(o,{href:"https://fedoramagazine.org/introduce-the-different-fedora-linux-editions/"},{default:a(()=>[...r[9]||(r[9]=[t("https://fedoramagazine.org/introduce-the-different-fedora-linux-editions/",-1)])]),_:1})]),e("p",null,[r[15]||(r[15]=t("作者：",-1)),n(o,{href:"https://fedoramagazine.org/author/armanwu/"},{default:a(()=>[...r[11]||(r[11]=[t("Arman Arisman",-1)])]),_:1}),r[16]||(r[16]=t(" 選題：",-1)),n(o,{href:"https://github.com/lkxed"},{default:a(()=>[...r[12]||(r[12]=[t("lkxed",-1)])]),_:1}),r[17]||(r[17]=t(" 譯者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:a(()=>[...r[13]||(r[13]=[t("geekpi",-1)])]),_:1}),r[18]||(r[18]=t(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:a(()=>[...r[14]||(r[14]=[t("wxy",-1)])]),_:1})]),e("p",null,[r[21]||(r[21]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...r[19]||(r[19]=[t("LCTT",-1)])]),_:1}),r[22]||(r[22]=t(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:a(()=>[...r[20]||(r[20]=[t("Linux中國",-1)])]),_:1}),r[23]||(r[23]=t(" 榮譽推出",-1))])])}const h=i(p,[["render",f]]);export{T as __pageData,h as default};
